"""Generated by solo-to-scale; edit `templates/tools/approval.py` in the plugin, then run upgrade.

Founder approval gates. Policy: founder/gates.json. Requests are GitHub issues labelled `needs-founder` and
`gate:<name>`; only a founder's own comment decides one:
  /approve            this one action
  /approve always     a standing rule for this gate and scope, until /revoke
  /reject <reason>    no; the agent stops and reports
  /revoke             withdraws an earlier approval
The latest founder command wins. Anything else, including bots, other people and labels, never counts.

  python tools/approval.py request <gate> --title "..." --why "..." [--impact "..."] [--scope "..."]
  python tools/approval.py check <gate> [--issue N | --scope "..."]   # exit 0 approved, 3 waiting, 4 no
  python tools/approval.py status <issue>
  python tools/approval.py inbox
  python tools/approval.py pr <number>     # CI: gated files need the founder-approved label, added by a founder

Fails closed: if GitHub can't be reached or anything is unclear, the answer is "not approved".
Python 3 standard library plus the gh CLI.
"""
from __future__ import annotations

import argparse
import fnmatch
import json
import os
import re
import subprocess
import sys
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402

APPROVED, WAITING, NO, ERROR = 0, 3, 4, 5
COMMAND = re.compile(r"^\s*/(approve|reject|revoke)\b[ \t]*(.*)$", re.IGNORECASE | re.MULTILINE)
LABEL, PR_LABEL = "needs-founder", "founder-approved"


def policy(root: Path = s.ROOT) -> dict[str, Any]:
    try:
        data = json.loads(s.read(root / "founder" / "gates.json") or "{}")
    except ValueError:
        data = {}
    return {"founders": [f.lower() for f in data.get("founders", [])], "gates": data.get("gates", {})}


def founders(pol: dict[str, Any], repo: str) -> set[str]:
    return set(pol["founders"]) or {repo.split("/")[0].lower()}


def decide(comments: list[dict[str, Any]], founder_logins: set[str]) -> dict[str, str]:
    """The latest founder command among the comments, in order. Non-founders never count."""
    result = {"state": "waiting", "kind": "", "note": ""}
    for c in comments:
        if (c.get("user") or {}).get("login", "").lower() not in founder_logins:
            continue
        for verb, rest in COMMAND.findall(c.get("body") or ""):
            verb, rest = verb.lower(), rest.strip()
            if verb == "approve":
                result = {"state": "approved", "kind": "always" if rest.lower().startswith("always") else "once", "note": rest}
            elif verb == "reject":
                result = {"state": "rejected", "kind": "", "note": rest}
            else:
                result = {"state": "revoked", "kind": "", "note": rest}
    return result


def gated_paths(pol: dict[str, Any], files: list[str]) -> dict[str, list[str]]:
    hits: dict[str, list[str]] = {}
    for name, gate in pol["gates"].items():
        for f in files:
            if any(fnmatch.fnmatch(f, p) for p in gate.get("paths", [])):
                hits.setdefault(name, []).append(f)
    return hits


def request_body(gate: str, what: str, why: str, impact: str, scope: str, role: str) -> str:
    return "\n".join([
        f"**Gate:** `{gate}`: {what}", f"**Requested by:** {role or 'an agent'}", f"**Scope:** {scope or 'this action only'}",
        "", "## Why", why or "(not given)", "", "## Impact, cost and reversibility", impact or "(not given)", "",
        "## Founder: reply with one line",
        "- `/approve`: this action only", "- `/approve always`: a standing rule for this gate and scope, until `/revoke`",
        "- `/reject <reason>`", "", "The agent waits and does nothing gated until you answer. Comments from anyone else don't count.",
    ])


# --- GitHub access (all reads fail closed) ---------------------------------------------------------------

def gh(*args: str, payload: dict | None = None) -> Any:
    cmd = ["gh", "api", *args]
    if payload is not None:
        cmd += ["--input", "-"]
    out = subprocess.run(cmd, input=json.dumps(payload) if payload is not None else None,
                         capture_output=True, text=True, check=True)
    return json.loads(out.stdout or "null")


def repo_name(root: Path = s.ROOT) -> str:
    env = os.environ.get("GITHUB_REPOSITORY")
    if env:
        return env
    repo = s.project(root).get("repo", "")
    if repo.count("/") == 1:
        return repo
    url = s.git(root, "remote", "get-url", "origin") or ""
    m = re.search(r"[:/]([^/:]+/[^/]+?)(?:\.git)?$", url)
    return m.group(1) if m else ""


def comments(repo: str, number: int) -> list[dict[str, Any]]:
    return gh(f"repos/{repo}/issues/{number}/comments?per_page=100") or []


def issue_state(repo: str, number: int, pol: dict[str, Any]) -> dict[str, str]:
    issue = gh(f"repos/{repo}/issues/{number}")
    labels = [lb["name"] for lb in issue.get("labels", [])]
    gate = next((lb.split(":", 1)[1] for lb in labels if lb.startswith("gate:")), "")
    return {**decide(comments(repo, number), founders(pol, repo)), "gate": gate, "title": issue.get("title", "")}


def standing_rule(repo: str, gate: str, scope: str, pol: dict[str, Any]) -> bool:
    found = gh(f"repos/{repo}/issues?labels={LABEL},gate:{gate}&state=all&per_page=100") or []
    for issue in found:
        if issue.get("pull_request"):
            continue
        d = decide(comments(repo, issue["number"]), founders(pol, repo))
        body = issue.get("body") or ""
        rule_scope = (re.search(r"\*\*Scope:\*\* (.*)", body) or [None, ""])[1].strip().lower()
        if d["state"] == "approved" and d["kind"] == "always" and (not scope or scope.lower() in rule_scope):
            return True
    return False


# --- commands -----------------------------------------------------------------------------------------

def cmd_request(a: argparse.Namespace, pol: dict[str, Any], repo: str) -> int:
    gate = pol["gates"].get(a.gate)
    if not gate:
        print(f"unknown gate {a.gate!r}; gates: {', '.join(pol['gates'])}")
        return ERROR
    if gate.get("mode") == "allow":
        print(f"gate {a.gate} is allow: no approval needed")
        return APPROVED
    if gate.get("mode") == "off":
        print(f"gate {a.gate} is founder-only: hand it to the founder as a founder item; don't request it")
        return NO
    body = request_body(a.gate, gate.get("what", ""), a.why, a.impact, a.scope, a.role)
    if a.dry_run:
        print(body)
        return WAITING
    issue = gh(f"repos/{repo}/issues", "-X", "POST",
               payload={"title": f"[approval] {a.title}", "body": body, "labels": [LABEL, f"gate:{a.gate}"]})
    print(f"#{issue['number']} {issue['html_url']}\nWaiting for the founder. Do nothing gated until it's approved.")
    return WAITING


def cmd_check(a: argparse.Namespace, pol: dict[str, Any], repo: str) -> int:
    gate = pol["gates"].get(a.gate)
    if not gate:
        print(f"unknown gate {a.gate!r}: not approved")
        return NO
    if gate.get("mode") == "allow":
        print("allowed")
        return APPROVED
    if gate.get("mode") == "off":
        print("founder-only: not approved")
        return NO
    if a.issue:
        st = issue_state(repo, a.issue, pol)
        if st["gate"] != a.gate:
            print(f"#{a.issue} is not a {a.gate} request: not approved")
            return NO
        print(f"#{a.issue}: {st['state']} {st['kind']}".rstrip())
        return {"approved": APPROVED, "waiting": WAITING}.get(st["state"], NO)
    ok = standing_rule(repo, a.gate, a.scope, pol)
    print("approved by a standing rule" if ok else "no standing rule: request approval")
    return APPROVED if ok else WAITING


def cmd_status(a: argparse.Namespace, pol: dict[str, Any], repo: str) -> int:
    st = issue_state(repo, a.issue, pol)
    print(f"#{a.issue} gate:{st['gate'] or '?'} {st['state']} {st['kind']} {st['note']}".rstrip())
    return {"approved": APPROVED, "waiting": WAITING}.get(st["state"], NO)


def cmd_inbox(a: argparse.Namespace, pol: dict[str, Any], repo: str) -> int:
    open_issues = [i for i in gh(f"repos/{repo}/issues?labels={LABEL}&state=open&per_page=100") or [] if not i.get("pull_request")]
    if not open_issues:
        print("No approvals waiting.")
    for i in open_issues:
        d = decide(comments(repo, i["number"]), founders(pol, repo))
        gate = next((lb["name"][5:] for lb in i.get("labels", []) if lb["name"].startswith("gate:")), "?")
        print(f"#{i['number']} [{gate}] {d['state']}: {i['title']}")
    return APPROVED


def cmd_pr(a: argparse.Namespace, pol: dict[str, Any], repo: str) -> int:
    files = [f["filename"] for f in gh(f"repos/{repo}/pulls/{a.number}/files?per_page=100") or []]
    hits = gated_paths(pol, files)
    if not hits:
        print("No gated files: no founder approval needed.")
        return APPROVED
    for gate, paths in hits.items():
        print(f"gate {gate}: {', '.join(paths)}")
    events = gh(f"repos/{repo}/issues/{a.number}/events?per_page=100") or []
    who = founders(pol, repo)
    approved = False
    for e in events:  # the latest founder label action wins
        if (e.get("label") or {}).get("name") == PR_LABEL and (e.get("actor") or {}).get("login", "").lower() in who:
            approved = e.get("event") == "labeled"
    if approved:
        print(f"Approved: a founder added {PR_LABEL}.")
        return APPROVED
    print(f"Needs founder approval: a founder must add the {PR_LABEL} label to this pull request.")
    return NO


def main(argv: list[str] | None = None) -> int:
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument("--root", type=Path, default=s.ROOT, help=argparse.SUPPRESS)
    ap = argparse.ArgumentParser(description="Founder approval gates")
    sub = ap.add_subparsers(dest="cmd", required=True)
    r = sub.add_parser("request", parents=[common])
    r.add_argument("gate")
    r.add_argument("--title", required=True)
    r.add_argument("--why", default="")
    r.add_argument("--impact", default="")
    r.add_argument("--scope", default="")
    r.add_argument("--role", default="")
    r.add_argument("--dry-run", action="store_true")
    c = sub.add_parser("check", parents=[common])
    c.add_argument("gate")
    c.add_argument("--issue", type=int)
    c.add_argument("--scope", default="")
    sub.add_parser("status", parents=[common]).add_argument("issue", type=int)
    sub.add_parser("inbox", parents=[common])
    sub.add_parser("pr", parents=[common]).add_argument("number", type=int)
    a = ap.parse_args(argv)
    pol, repo = policy(a.root), repo_name(a.root)
    if not pol["gates"]:
        print("founder/gates.json is missing or empty: every gated action is not approved")
        return NO
    if not repo:
        print("can't tell which GitHub repo this is: not approved")
        return ERROR
    try:
        return {"request": cmd_request, "check": cmd_check, "status": cmd_status,
                "inbox": cmd_inbox, "pr": cmd_pr}[a.cmd](a, pol, repo)
    except (subprocess.CalledProcessError, FileNotFoundError, ValueError, KeyError) as exc:
        print(f"GitHub unavailable or unexpected reply ({type(exc).__name__}): not approved")
        return ERROR


if __name__ == "__main__":
    sys.exit(main())
